./data/fulltext_screening_context_2026-07-10_docling_graph_direct_all235_clean_both_targets/fulltext_screening_input.jsonl:5:{"record_id": "full_2026-07-06__rec_001519", "candidate_id": "full_2026-07-06__rec_001519", "source_record_id": "rec_001519", "source_corpus": "include", "title": "BioGPT: A Generative Transformer-Based Framework for Personalized Genomic Medicine and Rare Disease Diagnosis", "abstract": "", "doi": "10.58496/mjaih/2025/015", "year": "", "venue": "", "sources": [], "selected_full_text_sections": "[data_source: Research Article > A B S T R A C T]\nThis  paper  introduces  BioGPT,  a  generative  transformer-based  framework  designed  to  advance personalized  genomic  medicine  and  rare  disease  diagnosis.  Unlike  conventional models that  process either genomic sequences or clinical narratives in isolation, BioGPT employs a cross-modal architecture that effectively fuses both data streams, enabling precise classification and interpretable natural language generation. The model is pre-trained on large-scale genomic and electronic health record datasets and fine-tun ed for rare disease tasks. Comprehensive experiments demonstrate BioGPT's superiority over state-of-the-art biomedical models, including RarePT, BioBERT, and DNABERT, with improvements of up to 10% in F1-score and over 20 BLEU points in justification fluency. Ablation studies highlight the essential contribution of cross-attention mechanisms in enhancing multi-modal synergy. Furthermore,  attention-based  interpretability  techniques  show  strong  alignment  with  expert  clinical markers, ensuring trust and transparency in diagnostic outputs. With sub-second inference times and compatibility with edge deployment strategies, BioGPT proves both effective and deployable in realworld clinical settings. This work establishes BioGPT as a robust, scalable, and explainable AI solution, setting a new benchmark for intelligent diagnostic systems in precision medicine.\n\n[input_representation: 3. PROPOSED SYSTEM: BIOGPT FRAMEWORK > 3.1 System Overview]\nBioGPT adopts an encoder-decoder transformer architecture tailored for biomedical domains. It processes two distinct input modalities:\n\n1. Genomic sequences, represented as overlapping k-mers\n2. Clinical narratives, comprising unstructured patient data such as symptoms, lab results, and case histories.\n\nThe  system  encodes  each  modality  independently,  fuses  them  within  a  shared  latent  space,  and  leverages  generative decoding to output disease hypotheses, gene associations, and clinical explanations.\n\nFig. 1. BioGPT System Architecture for Multi-Modal Rare Disease Diagnosis.\n\n<!-- image -->\n\nFigure 1 illustrates the high-level architecture of BioGPT, showcasing its end-to-end pipeline from input tokenization to rare disease diagnosis. The framework ingests genomic sequences (tokenized as k-mers) and clinical narratives (tokenized via BPE), which are independently embedded and passed through a multi-modal transformer fusion module. This fusion module integrates encoded signals from both modalities, enabling a holistic representation of patient data. The generative decoder  then  outputs  natural  language  explanations  alongside  structured  predictions.  The  architecture  supports  both pretraining and fine-tuning, and incorporates attention visualization, offering transparent, interpretable diagnostics.", "section_evidence": [{"section_type": "data_source", "heading": "A B S T R A C T", "heading_path": ["Research Article", "A B S T R A C T"], "heading_path_text": "Research Article > A B S T R A C T", "heading_level": 4, "line_start": 41, "line_end": 44, "text": "This  paper  introduces  BioGPT,  a  generative  transformer-based  framework  designed  to  advance personalized  genomic  medicine  and  rare  disease  diagnosis.  Unlike  conventional models that  process either genomic sequences or clinical narratives in isolation, BioGPT employs a cross-modal architecture that effectively fuses both data streams, enabling precise classification and interpretable natural language generation. The model is pre-trained on large-scale genomic and electronic health record datasets and fine-tun ed for rare disease tasks. Comprehensive experiments demonstrate BioGPT's superiority over state-of-the-art biomedical models, including RarePT, BioBERT, and DNABERT, with improvements of up to 10% in F1-score and over 20 BLEU points in justification fluency. Ablation studies highlight the essential contribution of cross-attention mechanisms in enhancing multi-modal synergy. Furthermore,  attention-based  interpretability  techniques  show  strong  alignment  with  expert  clinical markers, ensuring trust and transparency in diagnostic outputs. With sub-second inference times and compatibility with edge deployment strategies, BioGPT proves both effective and deployable in realworld clinical settings. This work establishes BioGPT as a robust, scalable, and explainable AI solution, setting a new benchmark for intelligent diagnostic systems in precision medicine.", "original_chars": 1404, "evidence_quote": "The model is pre-trained on large-scale genomic and electronic health record datasets", "evidence_section_heading": "Abstract", "contains_evidence_quote": true, "contains_chunk_excerpt": true, "chunk_id": 2, "pages": [1], "doc_item_refs": ["#/texts/18"], "docling_graph_node_id": "DataSourceEvidence_58ae3730bbdbde71", "docling_graph_provenance": {"document_id": "46d8fb7c1e05002aff3199b3f2bf7a9f", "match": "verbatim", "chunks": [2], "pages": [1], "refs": ["#/texts/18"], "spans": [{"chunk": 2, "start": 494, "end": 551}]}, "grounding_source": "docling_graph_provenance", "match_type": "verbatim", "source_markdown": "data/docling_include_no_vlm_2026-07-09/markdown/full_2026_07_06_rec_001519.md", "derivation_source": "docling_markdown_heading_boundary_from_docling_graph_heading_path", "section_coverage_ratio": 0.036779, "root_container": false, "full_document_lik